package com.bank.portfolio.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "holdings")
public class Holding {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "account_id", nullable = false)
    private String accountId;

    @Column(nullable = false)
    private String symbol;

    @Column(nullable = false)
    private int quantity;

    @Column(name = "avg_buy_price", nullable = false)
    private BigDecimal avgBuyPrice;

    @Column(name = "current_price")
    private BigDecimal currentPrice;

    @Column(name = "last_updated")
    private LocalDateTime lastUpdated;

    protected Holding() {}

    public Holding(String accountId, String symbol, int quantity, BigDecimal avgBuyPrice) {
        this.accountId = accountId;
        this.symbol = symbol;
        this.quantity = quantity;
        this.avgBuyPrice = avgBuyPrice;
        this.lastUpdated = LocalDateTime.now();
    }

    public BigDecimal getMarketValue() {
        return currentPrice != null
            ? currentPrice.multiply(BigDecimal.valueOf(quantity))
            : avgBuyPrice.multiply(BigDecimal.valueOf(quantity));
    }

    public BigDecimal getProfitLoss() {
        if (currentPrice == null) return BigDecimal.ZERO;
        return currentPrice.subtract(avgBuyPrice).multiply(BigDecimal.valueOf(quantity));
    }

    public String getAccountId() { return accountId; }
    public String getSymbol() { return symbol; }
    public int getQuantity() { return quantity; }
    public BigDecimal getAvgBuyPrice() { return avgBuyPrice; }
    public BigDecimal getCurrentPrice() { return currentPrice; }
}
