package com.bank.portfolio.repository;

import com.bank.portfolio.model.Holding;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.context.annotation.Primary;
import org.springframework.stereotype.Repository;
import jakarta.persistence.EntityManager;
import java.util.List;

@Repository("jpaPortfolioRepository")
@Primary  // default when no qualifier specified
@RequiredArgsConstructor
@Slf4j
public class JpaPortfolioRepository implements PortfolioRepository {

    private final EntityManager entityManager;

    @Override
    public List<Holding> findByAccountId(String accountId) {
        log.info("[JPA] Querying active holdings for {}", accountId);
        return entityManager.createQuery(
            "SELECT h FROM Holding h WHERE h.accountId = :accountId", Holding.class)
            .setParameter("accountId", accountId)
            .getResultList();
    }

    @Override
    public String getSourceName() { return "JPA (Primary Database)"; }
}
