package com.bank.portfolio.service;

import com.bank.portfolio.repository.PortfolioRepository;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.Map;

@Service
@Slf4j
public class ComplianceService {

    private final Map<String, PortfolioRepository> repoMap;

    // Map injection: keys = bean names
    public ComplianceService(Map<String, PortfolioRepository> repoMap) {
        this.repoMap = repoMap;
        log.info("ComplianceService loaded repos: {}", repoMap.keySet());
    }

    public void auditAccount(String accountId, boolean includeArchive) {
        // Always check active holdings
        repoMap.get("jpaPortfolioRepository").findByAccountId(accountId);

        // Optionally check archive
        if (includeArchive) {
            repoMap.get("archivePortfolioRepository").findByAccountId(accountId);
        }
    }
}
